function coloredCells(n) {
  // The blue cells are exactly those within n - 1 side steps of the first one: |x| + |y| <= n - 1.
  const reach = n - 1;
  let total = 0;
  for (let x = -reach; x <= reach; x++) {
    const spare = reach - Math.abs(x);
    total += 2 * spare + 1;
  }
  return total;
}

